#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# vercel_env NAME VALUE prints the one line to paste into Vercel's dashboard.
# The Vercel CLI isn't assumed to be installed, so env vars are set by hand in
# Project Settings → Environment Variables; this just keeps the instruction
# in one place instead of repeating it per stage.
vercel_env() {
  printf '  %s→ Vercel env var:%s %s = %s\n' "$BLUE" "$RESET" "$1" "$2"
}

run_wizard() {

TOTAL_STAGES=8

banner "Issue #25: provision GitHub App + Vercel Hobby project"

# ── Stage 1: webhook secret ────────────────────────────────────────────────
stage "Generate the webhook secret"
say "GitHub signs every webhook delivery with this secret (verifySignature in"
say "src/webhook/webhook-signature.ts checks it); generate it locally rather"
say "than inventing one by hand."
if command -v openssl >/dev/null 2>&1; then
  GITHUB_WEBHOOK_SECRET=$(openssl rand -hex 32)
  say "Generated: $GITHUB_WEBHOOK_SECRET"
else
  warn "openssl not found; paste any high-entropy random string instead."
  ask_secret GITHUB_WEBHOOK_SECRET "Paste a random secret (32+ chars):"
fi
write_env GITHUB_WEBHOOK_SECRET "$GITHUB_WEBHOOK_SECRET"
note "keep this value on screen, you'll paste it into the GitHub App form next"
pause "Copied it? Press Enter to continue"

# ── Stage 2: create the GitHub App ─────────────────────────────────────────
stage "Create the GitHub App"
say "Single-tenant App per ADR-0001: owned by your account, installed only on"
say "the target repo(s)."
open_url "https://github.com/settings/apps/new"
step "GitHub App name: anything unique (e.g. 'ai-code-reviewer-yourname')."
step "Homepage URL: this repo's URL (https://github.com/Hamza-339/ai-code-reviewer)."
step "Webhook → Active: checked. Webhook URL: use a placeholder for now"
step "  (e.g. https://example.com/webhook/github) — you'll fix this in Stage 5"
step "  once the Vercel project exists."
step "Webhook secret: paste the value generated in Stage 1."
step "Repository permissions → Pull requests: Read and write."
step "Repository permissions → Contents: Read-only."
step "Subscribe to events: check 'Pull request'."
step "Where can this GitHub App be installed?: Only on this account."
step "Click 'Create GitHub App'."
say "On the resulting App settings page:"
step "Copy the 'App ID' near the top."
ask GITHUB_APP_ID "Paste the App ID:"
step "The page URL is github.com/settings/apps/<slug> — copy <slug>."
ask GITHUB_APP_SLUG "Paste the App slug:"
write_env GITHUB_APP_ID "$GITHUB_APP_ID"
write_env GITHUB_APP_SLUG "$GITHUB_APP_SLUG"

# ── Stage 3: generate and capture the private key ──────────────────────────
stage "Generate the App's private key"
say "Still on the App settings page:"
step "Scroll to 'Private keys' → click 'Generate a private key'."
step "A .pem file downloads automatically."
note "the key is never shown again after this, keep the download"
ask GITHUB_APP_PRIVATE_KEY_PATH "Paste the full path to the downloaded .pem file:"
if [[ -f "$GITHUB_APP_PRIVATE_KEY_PATH" ]]; then
  GITHUB_APP_PRIVATE_KEY=$(cat "$GITHUB_APP_PRIVATE_KEY_PATH")
  write_env GITHUB_APP_PRIVATE_KEY "$GITHUB_APP_PRIVATE_KEY"
else
  warn "couldn't read that path; set GITHUB_APP_PRIVATE_KEY in $ENV_FILE by hand later"
  SKIPPED+=("GITHUB_APP_PRIVATE_KEY: read the .pem manually and write_env it")
fi

# ── Stage 4: create the Vercel Hobby project ───────────────────────────────
stage "Create the Vercel Hobby project"
say "Per ADR-0002: Vercel Hobby, no credit card, non-commercial single-tenant use."
open_url "https://vercel.com/new"
step "Sign up / log in with GitHub if you haven't already (no card required)."
step "Import this repo (Hamza-339/ai-code-reviewer) as a new project, or create"
step "  an empty project reserving a name if the deploy wiring (#27) isn't ready yet."
step "Confirm the plan shown is 'Hobby' (free)."
step "On the project's Overview page, copy its production domain"
step "  (e.g. https://your-project.vercel.app)."
ask VERCEL_PROJECT_URL "Paste the project's production URL:"
write_env VERCEL_PROJECT_URL "$VERCEL_PROJECT_URL"

# ── Stage 5: point the GitHub App's webhook at the real URL ───────────────
stage "Point the webhook at the Vercel project"
say "Back on the GitHub App's settings page:"
open_url "https://github.com/settings/apps/$GITHUB_APP_SLUG"
step "Webhook URL: replace the placeholder with"
step "  ${VERCEL_PROJECT_URL%/}/webhook/github"
step "Click 'Save changes'."
confirm "Saved the real webhook URL?" || warn "remember to come back and save it"

# ── Stage 6: install the App and capture the installation id ──────────────
stage "Install the App on the target repo(s)"
open_url "https://github.com/settings/apps/$GITHUB_APP_SLUG/installations"
step "Click 'Install', choose your account, and select the target repo(s)"
step "  (e.g. only Hamza-339/ai-code-reviewer)."
step "After installing you land on a URL like"
step "  github.com/settings/installations/<installation-id> — copy <installation-id>."
ask GITHUB_APP_INSTALLATION_ID "Paste the installation ID:"
write_env GITHUB_APP_INSTALLATION_ID "$GITHUB_APP_INSTALLATION_ID"

# ── Stage 7: Anthropic API key ──────────────────────────────────────────────
stage "Get an Anthropic API key"
open_url "https://console.anthropic.com/settings/keys"
step "Click 'Create Key', name it (e.g. 'ai-code-reviewer'), copy the key."
note "it starts with sk-ant- and is shown only once"
ask_secret ANTHROPIC_API_KEY "Paste the Anthropic API key:"
write_env ANTHROPIC_API_KEY "$ANTHROPIC_API_KEY"

# ── Stage 8: set everything as Vercel environment variables ───────────────
stage "Set environment variables in Vercel"
open_url "${VERCEL_PROJECT_URL%/}"
step "Open this project → Settings → Environment Variables."
step "Add each of the following (apply to Production, Preview, and Development):"
vercel_env "ANTHROPIC_API_KEY" "$ANTHROPIC_API_KEY"
vercel_env "GITHUB_APP_ID" "$GITHUB_APP_ID"
vercel_env "GITHUB_APP_SLUG" "$GITHUB_APP_SLUG"
vercel_env "GITHUB_APP_INSTALLATION_ID" "$GITHUB_APP_INSTALLATION_ID"
vercel_env "GITHUB_WEBHOOK_SECRET" "$GITHUB_WEBHOOK_SECRET"
note "GITHUB_APP_PRIVATE_KEY: paste the full .pem contents (all lines, incl."
note "  -----BEGIN/END----- markers) as the value — see $ENV_FILE for the exact text"
confirm "All six variables saved in Vercel?" || SKIPPED+=("Set the Vercel env vars by hand from $ENV_FILE")

finish
say "Hand these to the deploy ticket (#27):"
say "  GITHUB_APP_ID=$GITHUB_APP_ID"
say "  GITHUB_APP_INSTALLATION_ID=$GITHUB_APP_INSTALLATION_ID"
say "  GITHUB_APP_SLUG=$GITHUB_APP_SLUG"
say "  Vercel project: $VERCEL_PROJECT_URL"
note "full secret values are in $ENV_FILE (gitignored) — never paste them into chat, issues, or commits"
}

run_wizard "$@"; exit
